\title{Transfinite Values in Countably Branching Winning Games:\\From $\omega$ to $\omega^\omega$}
\author{Aristotle}
\date{July 18, 2026}
\begin{document}
\maketitle

\begin{abstract}
Infinite chess motivates winning positions for which checkmate is inevitable although no finite move bound is uniform over all defenses. We isolate the ordinal timing mechanism in well-founded, countably branching winning game trees. A terminal node has value $0$, a forced move takes a successor, and an adversarial countable choice takes a supremum. Sequential composition realizes ordinal addition in the order dictated by traversal. From unbounded finite delay we construct games of exact value $\omega^n$ for every natural number $n$, and a diagonal construction of exact value $\omega^\omega$. The values strictly increase and each is the least sufficient forcing budget. These are abstract game-tree results; realization by legal chess positions is a separate geometric problem.
\end{abstract}

\section{Introduction}
In a finite game graph, a forced win admits a finite uniform bound. Infinite games can separate branchwise termination from uniform boundedness: an adversary may choose any finite delay, so every play ends although no natural number bounds all plays. Ordinals measure this behavior. The value $\omega$ records an unbounded family of finite delays; $\omega^2$ records an unbounded finite sequence of omega-scale phases; and $\omega^\omega$ gathers every finite nesting depth.

We use a minimal timing model. White has forced continuations and Black has countable delaying choices. The model retains the ordinal mechanism while omitting board geometry. We prove composition, finite-power, strict-growth, diagonal, and exact lower-bound theorems.

\section{Ordinal preliminaries}
The natural numbers are the finite ordinals and
\[
\omega=\sup_{n<\omega}n.
\]
Ordinal addition and multiplication encode ordered concatenation and need not commute: $1+\omega=\omega$ but $\omega+1>\omega$. For a sequence $(\alpha_n)$, its supremum is the least common upper bound. Left addition is continuous:
\[
a+\sup_{n<\omega}\alpha_n=\sup_{n<\omega}(a+\alpha_n).
\]
Furthermore,
\[
\omega^0=1,\qquad \omega^{n+1}=\omega^n\omega,
\qquad \omega^\omega=\sup_{n<\omega}\omega^n.
\]

\section{Game trees and values}
\begin{definition}[Countably branching forced-win tree]
A game is generated by a terminal node $\Mate$, a forced node $\Step(G)$ with one child, and a Black-choice node $\Choice((G_n)_{n<\omega})$ with countably many children.
\end{definition}

\begin{definition}[Game value]
Define $V$ recursively by
\[
V(\Mate)=0,\qquad V(\Step(G))=V(G)+1,
\]
and
\[
V(\Choice((G_n)))=\sup_{n<\omega}(V(G_n)+1).
\]
An ordinal $\alpha$ is a sufficient forcing budget for $G$ when $V(G)\leq\alpha$.
\end{definition}

\begin{proposition}[Least-budget principle]
For every game $G$, the ordinal $V(G)$ is the unique least sufficient forcing budget.
\end{proposition}
\begin{proof}
Reflexivity makes $V(G)$ sufficient. Any sufficient $\alpha$ satisfies $V(G)\leq\alpha$ by definition. Antisymmetry gives uniqueness.
\end{proof}

\section{Sequential composition}
\begin{definition}[Grafting]
The graft $A\triangleright B$ replaces every terminal leaf of $A$ by a fresh copy of $B$. Thus $\Mate\triangleright B=B$, grafting commutes with $\Step$, and it distributes over all children of $\Choice$.
\end{definition}

\begin{lemma}[Continuity of left addition]
For every ordinal $a$ and sequence $(b_n)_{n<\omega}$,
\[
a+\sup_n b_n=\sup_n(a+b_n).
\]
\end{lemma}
\begin{proof}
The map $b\mapsto a+b$ is increasing and continuous in its right argument. Hence it preserves the indicated supremum.
\end{proof}

\begin{theorem}[Sequential Composition Theorem]
For all games $A$ and $B$,
\[
V(A\triangleright B)=V(B)+V(A).
\]
\end{theorem}
\begin{proof}
Use structural induction on $A$. The terminal case reduces to $V(B)=V(B)+0$. At a forced node, apply the induction hypothesis and associativity. At a choice node with children $A_n$,
\begin{align*}
V(\Choice((A_n))\triangleright B)
 &=\sup_n(V(A_n\triangleright B)+1)\\
 &=\sup_n(V(B)+V(A_n)+1)\\
 &=V(B)+\sup_n(V(A_n)+1),
\end{align*}
where the final equality is continuity of left addition. The last expression is $V(B)+V(A)$.
\end{proof}

\begin{corollary}[Finite iteration]
If $A^{[k]}$ is the sequential composition of $k$ copies of $A$, with $A^{[0]}=\Mate$, then
\[
V(A^{[k]})=V(A)\,k.
\]
\end{corollary}
\begin{proof}
Induct on $k$ and apply the composition theorem at the successor step.
\end{proof}

\section{The value $\omega$}
Let $F_n$ be a chain of $n$ forced steps followed by mate.
\begin{lemma}[Finite countdown]
For every $n<\omega$, $V(F_n)=n$.
\end{lemma}
\begin{proof}
Induct on $n$. The empty chain has value $0$ and each added step takes a successor.
\end{proof}

Let $G_\omega=\Choice((F_n)_{n<\omega})$.
\begin{theorem}[Mate-in-Omega Theorem]
The exact value of $G_\omega$ is $\omega$.
\end{theorem}
\begin{proof}
The value equation gives
\[
V(G_\omega)=\sup_{n<\omega}(n+1)=\omega.
\]
Every term is finite, while the terms are cofinal among the finite ordinals.
\end{proof}

\begin{corollary}[No finite bound]
No natural number is a sufficient forcing budget for $G_\omega$.
\end{corollary}
\begin{proof}
Every $N<\omega=V(G_\omega)$, so the least-budget principle applies. Equivalently, Black chooses a countdown longer than $N$.
\end{proof}

\section{Finite powers of $\omega$}
\begin{definition}[Power games]
Let $G_0=\Step(\Mate)$. Given $G_n$, define $G_{n+1}$ as the Black-choice game whose $k$th continuation is $G_n^{[k]}$.
\end{definition}

\begin{lemma}[Unbounded finite repetition]
If $v>0$, then
\[
\sup_{k<\omega}(vk+1)=v\omega.
\]
\end{lemma}
\begin{proof}
For the upper bound, $vk+1\leq v(k+1)\leq v\omega$. For the reverse bound, every $vk$ is at most one of the displayed terms; taking the supremum over $k$ gives $v\omega$.
\end{proof}

\begin{theorem}[Finite-Power Hierarchy Theorem]
For every natural number $n$,
\[
V(G_n)=\omega^n.
\]
\end{theorem}
\begin{proof}
The base game has value $1=\omega^0$. If $V(G_n)=\omega^n$, finite iteration gives $V(G_n^{[k]})=\omega^n k$. Therefore
\[
V(G_{n+1})=\sup_{k<\omega}(\omega^n k+1)
=\omega^n\omega=\omega^{n+1}.
\]
Induction completes the proof.
\end{proof}

\begin{corollary}[Explicit target values]
There are explicit games of exact values $\omega$, $\omega^2$, and $\omega^3$.
\end{corollary}

\begin{theorem}[Strict growth]
If $m<n$, then $V(G_m)<V(G_n)$.
\end{theorem}
\begin{proof}
Substitute $V(G_j)=\omega^j$ and use strict monotonicity of exponentiation with base $\omega>1$.
\end{proof}

\section{The diagonal value $\omega^\omega$}
\begin{definition}[Diagonal game]
Let $D=\Choice((G_n)_{n<\omega})$; Black chooses which finite-power game White must solve.
\end{definition}

\begin{lemma}[Diagonal supremum]
\[
\sup_{n<\omega}(\omega^n+1)=\omega^\omega.
\]
\end{lemma}
\begin{proof}
Each term is at most $\omega^{n+1}$ and hence below $\omega^\omega$. Conversely, for every $x<\omega^\omega$, cofinality of the finite powers supplies $n$ with $x<\omega^n$, so $x$ lies below the displayed supremum.
\end{proof}

\begin{theorem}[Diagonal Value Theorem]
The diagonal game has exact value
\[
V(D)=\omega^\omega.
\]
\end{theorem}
\begin{proof}
By the choice rule, the finite-power theorem, and the diagonal supremum,
\[
V(D)=\sup_n(V(G_n)+1)=\sup_n(\omega^n+1)=\omega^\omega.
\]
\end{proof}

\begin{corollary}[Universal lower bound]
For every $\alpha<\omega^\omega$, the budget $\alpha$ is insufficient for $D$. In particular, no $\omega^n$ suffices.
\end{corollary}
\begin{proof}
Sufficiency would imply $\omega^\omega=V(D)\leq\alpha$, contradicting the hypothesis.
\end{proof}

\section{Algorithms and illustrations}
A finite experiment must truncate each countable choice to $0,\ldots,K$. A simple maximum-delay profile is
\[
T_0(K)=1,\qquad T_{n+1}(K)=K T_n(K)+1.
\]
It can be evaluated in $O(d)$ arithmetic operations through depth $d$. This is a finite shadow, not the ordinal value formula. Symbolically, $\omega^n$ can be stored by exponent $n$, with a separate marker for $\omega^\omega$; comparison then reduces to comparing exponents and placing the marker above every finite one.

No finite cutoff proves a transfinite lower bound. Sampling the first million choices still omits larger choices. Exactness rests on supremum and cofinality arguments.

\section{Applications and scope}
The same architecture describes adversarial schedulers, nested termination arguments, rewriting systems, and sequential game semantics. Grafting explains why ordered tasks compose by ordinal rather than commutative arithmetic.

For infinite chess, these trees are timing blueprints, not legal positions on $\mathbb Z^2$. A board realization must implement forced steps, countable choices, and grafting with pieces while proving isolation and preventing long-range shortcuts. The model also omits genuine White choices, which in a full minimax theory would take infima over successor values.

\section{Worked examples}
A chain of four forced steps has value $4$. A finite Black menu of chains of lengths $0,1,2,3$ also remains finite, with value $4$; only an unbounded natural menu reaches $\omega$. Two omega-scale modules in sequence have value $\omega+\omega=\omega\cdot2$. Allowing Black an unbounded finite number of such modules gives $\omega^2$.

Direction matters: $1+\omega=\omega$, while $\omega+1>\omega$. Likewise, if a budget $\omega^7$ is proposed for the diagonal game, Black chooses $G_8$ and defeats it. More generally, every ordinal below $\omega^\omega$ lies below a sufficiently high finite power.

\section{Future work}
A concrete theory should define infinite-board positions, legal sliding paths, attacks, check, checkmate, promotion, and alternating strategies. Gadget interfaces should provide ports, isolation invariants, and simulation theorems. Realizing forced steps, countable choice, and grafting would permit compositions at $\omega$, $\omega^2$, and $\omega^3$. The $\omega^\omega$ stage additionally requires one locally finite board containing all finite levels without violating initial-support conventions. Adding genuine White-choice nodes would extend the model to general minimax trees.

\section{Conclusion}
Countable hostile choice turns unbounded finite delay into $\omega$. Sequential composition realizes ordinal addition, finite repetition and recursion realize every $\omega^n$, and diagonalization realizes $\omega^\omega$. Every value is exact: it is sufficient, and all smaller budgets fail. The hierarchy is a precise blueprint for transfinite timing in infinite games, while its realization by orthodox chess pieces remains an open geometric construction problem.
\end{document}

